CREATE TABLE plugin_lrs_statement (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  seq bigint NOT NULL,
  stored_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  payload jsonb NOT NULL
);
COMMENT ON COLUMN plugin_lrs_statement.payload IS 'Annex L: JSON, 0.5-4 KiB typical, p99 <= 32 KiB';
CREATE INDEX plugin_lrs_statement_keyset ON plugin_lrs_statement (tenant_id, stored_at, id);

CREATE FUNCTION plugin_lrs_statement_reject_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  RAISE EXCEPTION 'plugin_lrs_statement is append-only';
END;
$fn$;

CREATE TRIGGER plugin_lrs_statement_append_only
  BEFORE UPDATE OR DELETE ON plugin_lrs_statement
  FOR EACH ROW
  EXECUTE FUNCTION plugin_lrs_statement_reject_mutation();

REVOKE UPDATE, DELETE ON plugin_lrs_statement FROM PUBLIC;
